/**
 * A formiga prateada do Saara — porte de `componentes/viz/formiga_prata.js`.
 *
 * A Cataglyphis bombycina forrageia ao meio-dia no Saara, quando a areia passa
 * dos 60 °C — justamente porque é a hora em que os predadores dela não saem. Ela
 * sobrevive por um balanço térmico de duas pontas, e as duas dependem do mesmo
 * pelo triangular: ele REFLETE a luz do sol e IRRADIA o calor do corpo. O corpo
 * tem de ficar abaixo de ~53 °C; acima disso, ela morre.
 *
 * Por isso há dois controles e um só termômetro: é o veredito dos dois juntos.
 */

import { criarCanvas2d, seta } from '../../../viz/canvas2d.ts';
import { type EstadoDaViz, infoDe, limitar, numeroDe, paleta, texto, titulo } from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Faixa da escala do termômetro, em °C. */
const MIN = 35;
const MAX = 75;

const formigaPrata: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function termometro(
    ctx: CanvasRenderingContext2D,
    L: number,
    A: number,
    temperatura: number,
    letal: number,
    ok: boolean,
  ): void {
    const cor = paleta();
    const x = L - 40;
    const topo = A * 0.2;
    const altura = A * 0.54;
    const tinta = ok ? cor.verde : cor.erro;

    const yDe = (v: number): number =>
      topo + altura - ((limitar(v, MIN, MAX) - MIN) / (MAX - MIN)) * altura;

    ctx.fillStyle = cor.palha;
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.fillRect(x - 8, topo - 6, 16, altura + 26);
    ctx.strokeRect(x - 8, topo - 6, 16, altura + 26);

    ctx.fillStyle = tinta;
    const y = yDe(temperatura);
    ctx.fillRect(x - 4, y, 8, topo + altura - y + 8);
    ctx.beginPath();
    ctx.arc(x, topo + altura + 10, 9, 0, Math.PI * 2);
    ctx.fill();

    // A linha do limite letal — a régua contra a qual tudo se mede.
    const yLetal = yDe(letal);
    ctx.strokeStyle = cor.erro;
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 3]);
    ctx.beginPath();
    ctx.moveTo(x - 16, yLetal);
    ctx.lineTo(x + 12, yLetal);
    ctx.stroke();
    ctx.setLineDash([]);

    const miudo = limitar(A * 0.032, 8, 11);
    texto(ctx, `letal ${Math.round(letal)}°`, x - 19, yLetal, miudo, {
      cor: cor.erro,
      alinhamento: 'right',
      peso: 700,
    });
    texto(
      ctx,
      Number.isFinite(temperatura) ? `${temperatura.toFixed(0)}°C` : '—',
      x,
      topo - miudo * 1.6,
      miudo * 1.25,
      { cor: tinta, peso: 800 },
    );
    texto(ctx, ok ? 'SEGURA' : 'QUENTE', x, topo + altura + 30, miudo * 1.1, {
      cor: tinta,
      peso: 800,
    });
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const reflexao = numeroDe(valores, 'refl', 0);
    const emissao = numeroDe(valores, 'emis', 0);
    const temperatura = numeroDe(info, 'temp', Number.NaN);
    const letal = numeroDe(info, 'limite', 53);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'Meio-dia no Saara');

    // A areia escaldante.
    const solo = A * 0.74;
    const areia = ctx.createLinearGradient(0, solo, 0, A);
    areia.addColorStop(0, '#e8c07a');
    areia.addColorStop(1, '#c99a55');
    ctx.fillStyle = areia;
    ctx.fillRect(0, solo, L, A - solo);

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 2;
    for (let i = 0; i < 5; i++) {
      const x = L * (0.12 + i * 0.19);
      ctx.beginPath();
      for (let y = solo; y > solo - 26; y -= 3) {
        const dx = Math.sin((y + t * 60 + i * 40) * 0.15) * 4;
        if (y === solo) ctx.moveTo(x + dx, y);
        else ctx.lineTo(x + dx, y);
      }
      ctx.stroke();
    }

    // O sol, sempre a pino.
    const solX = L * 0.8;
    const solY = A * 0.22;
    ctx.fillStyle = cor.ouro;
    ctx.beginPath();
    ctx.arc(solX, solY, 18, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = cor.ouro;
    ctx.lineWidth = 2;
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(solX + Math.cos(a) * 22, solY + Math.sin(a) * 22);
      ctx.lineTo(solX + Math.cos(a) * 30, solY + Math.sin(a) * 30);
      ctx.stroke();
    }

    // A formiga.
    const fx = L * 0.4;
    const fy = solo - 6;

    ctx.fillStyle = ok ? '#cfe3ff' : '#b8bcc4';
    for (const [dx, r] of [
      [-16, 11],
      [0, 8],
      [12, 8],
    ]) {
      ctx.beginPath();
      ctx.ellipse(fx + (dx ?? 0), fy - (r ?? 0) * 0.7, r ?? 0, (r ?? 0) * 0.85, 0, 0, Math.PI * 2);
      ctx.fill();
    }

    // Os pelos triangulares — a peça que faz as duas coisas.
    ctx.fillStyle = ok ? '#e6f0ff' : '#d2d6de';
    for (let i = -20; i <= 14; i += 4) {
      ctx.beginPath();
      ctx.moveTo(fx + i, fy - 15);
      ctx.lineTo(fx + i + 2, fy - 22);
      ctx.lineTo(fx + i + 4, fy - 15);
      ctx.closePath();
      ctx.fill();
    }

    ctx.strokeStyle = '#8a6a44';
    ctx.lineWidth = 1.5;
    for (const dx of [-10, 0, 8]) {
      ctx.beginPath();
      ctx.moveTo(fx + dx, fy);
      ctx.lineTo(fx + dx - 5, fy + 8);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(fx + dx, fy);
      ctx.lineTo(fx + dx + 5, fy + 8);
      ctx.stroke();
    }

    // Os raios que chegam.
    const raio = ctx.createLinearGradient(solX, solY, fx, fy);
    raio.addColorStop(0, 'rgb(230 175 20 / 65%)');
    raio.addColorStop(1, 'rgb(230 175 20 / 15%)');
    ctx.strokeStyle = raio;
    ctx.lineWidth = 3;
    for (const desvio of [-8, 0, 8]) {
      ctx.beginPath();
      ctx.moveTo(solX - 12, solY + 12);
      ctx.lineTo(fx + desvio, fy - 18);
      ctx.stroke();
    }

    const miudo = limitar(A * 0.036, 9, 12);

    // A reflexão: setas voltando ao céu.
    const setas = Math.round(reflexao / 20);
    for (let i = 0; i < setas; i++) {
      const angulo = -Math.PI / 2 + (i - (setas - 1) / 2) * 0.35;
      seta(
        ctx,
        fx,
        fy - 20,
        fx + Math.cos(angulo) * 34,
        fy - 20 + Math.sin(angulo) * 34,
        cor.azul,
        2,
      );
    }
    texto(ctx, `reflete ${Math.round(reflexao)}%`, fx, fy - 68, miudo, {
      cor: cor.azul,
      peso: 700,
    });

    // A emissão: ondas de calor saindo do corpo.
    const ondas = Math.round(emissao / 20);
    ctx.strokeStyle = '#c2662f';
    ctx.lineWidth = 1.8;
    for (let i = 0; i < ondas; i++) {
      const yy = fy - 26 - i * 7 - ((t * 20) % 7);
      ctx.beginPath();
      for (let x = fx + 16; x <= fx + 44; x += 3) {
        const dy = Math.sin((x + t * 80) * 0.4) * 2.5;
        if (x === fx + 16) ctx.moveTo(x, yy + dy);
        else ctx.lineTo(x, yy + dy);
      }
      ctx.stroke();
    }
    texto(ctx, `irradia ${Math.round(emissao)}%`, fx + 30, fy - 62, miudo, {
      cor: '#c2662f',
      peso: 700,
      alinhamento: 'left',
    });

    termometro(ctx, L, A, temperatura, letal, ok);
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default formigaPrata;
